public class UsHesaplayici {
    public static long usAl(int taban, int us) {
        long sonuc = 1;
        for (int i = 0; i < us; i++) {
            sonuc *= taban;
        }
        return sonuc;
    }

    public static void main(String[] args) {
        System.out.println("2^5 = " + usAl(2, 5));
    }
}

