public class MinMaxDizi {
    public static void main(String[] args) {
        int[] dizi = {12, 45, 3, 89, 24, 67};
        int min = dizi[0];
        int max = dizi[0];

        for (int i = 1; i < dizi.length; i++) {
            if (dizi[i] < min) min = dizi[i];
            if (dizi[i] > max) max = dizi[i];
        }

        System.out.println("En küçük: " + min);
        System.out.println("En büyük: " + max);
    }
}

public class KosegenToplami {
    public static void main(String[] args) {
        int[][] matris = {
            {3, 8, 1},
            {5, 9, 2},
            {4, 7, 6}
        };

        int toplam = 0;
        for (int i = 0; i < matris.length; i++) {
            toplam += matris[i][i];
        }

        System.out.println("Asal Köşegen Toplamı: " + toplam); // 3 + 9 + 6 = 18
    }
}

