public class RekursifUs {
    public static int usHesapla(int taban, int us) {
        if (us == 0) {
            return 1; // Taban durum (Base case)
        } else {
            return taban * usHesapla(taban, us - 1); // Rekürsif adım
        }
    }

    public static void main(String[] args) {
        System.out.println("3^4 = " + usHesapla(3, 4)); // 81
    }
}

